options(stringsAsFactors = FALSE)

# Stage 13: main-text variance-share table -----------------------------------
# Produces a compact Base A, both-sex table from the log-scale variance
# decomposition generated by Stage 10. The table reports percentage shares for
# the PRENEC-derived and literature-based FIT-sensitivity scenarios.

script_directory <- function() {
  args <- commandArgs(trailingOnly = FALSE)
  file_arg <- grep("^--file=", args, value = TRUE)
  if (length(file_arg) == 0L) {
    return(normalizePath(getwd(), winslash = "/", mustWork = TRUE))
  }
  dirname(normalizePath(
    sub("^--file=", "", file_arg[[1]]),
    winslash = "/",
    mustWork = TRUE
  ))
}

project_directory <- Sys.getenv(
  "PRENEC_PROJECT_ROOT",
  unset = normalizePath(
    file.path(script_directory(), ".."),
    winslash = "/",
    mustWork = TRUE
  )
)
joint_output_directory <- Sys.getenv(
  "PRENEC_JOINT_BOOTSTRAP_OUTPUT_DIR",
  unset = file.path(project_directory, "results", "joint_bootstrap")
)
input_file <- file.path(
  joint_output_directory,
  "joint_bootstrap_log_variance_shares.tsv"
)
output_directory <- file.path(joint_output_directory, "tables")

if (!file.exists(input_file)) {
  stop("Variance-share input was not found: ", input_file, call. = FALSE)
}
dir.create(output_directory, recursive = TRUE, showWarnings = FALSE)

shares <- read.delim(input_file, check.names = FALSE)
required_columns <- c(
  "Assignment", "Population", "Estimand", "Lesion_key", "Lesion",
  "FIT_sensitivity_scenario", "Data_variance_share", "FIT_variance_share",
  "Colonoscopy_variance_share"
)
missing_columns <- setdiff(required_columns, names(shares))
if (length(missing_columns) > 0L) {
  stop(
    "Variance-share input is missing: ",
    paste(missing_columns, collapse = ", "),
    call. = FALSE
  )
}

table_long <- shares[
  shares$Assignment == "A" & shares$Population == "Both sexes",
  required_columns,
  drop = FALSE
]

lesion_order <- c("low_risk", "high_risk", "adenoma_total", "cancer")
estimand_order <- c(
  "Lesion detection under universal colonoscopy",
  "Prevalence"
)
scenario_order <- c("PRENEC", "Literature")

if (nrow(table_long) != 16L ||
    any(table(
      factor(table_long$Lesion_key, levels = lesion_order),
      factor(table_long$Estimand, levels = estimand_order),
      factor(
        table_long$FIT_sensitivity_scenario,
        levels = scenario_order
      )
    ) != 1L)) {
  stop("Expected one row for each of the 16 requested table cells.", call. = FALSE)
}

share_columns <- c(
  "Data_variance_share", "FIT_variance_share",
  "Colonoscopy_variance_share"
)
if (any(!is.finite(as.matrix(table_long[share_columns]))) ||
    any(as.matrix(table_long[share_columns]) < 0) ||
    max(abs(rowSums(table_long[share_columns]) - 1)) > 1e-10) {
  stop("Variance shares must be finite, non-negative, and sum to one.", call. = FALSE)
}

table_long$Screening_data_share_percent <-
  100 * table_long$Data_variance_share
table_long$FIT_sensitivity_share_percent <-
  100 * table_long$FIT_variance_share
table_long$Colonoscopy_sensitivity_share_percent <-
  100 * table_long$Colonoscopy_variance_share

table_long$Lesion_key <- factor(table_long$Lesion_key, levels = lesion_order)
table_long$Estimand <- factor(table_long$Estimand, levels = estimand_order)
table_long$FIT_sensitivity_scenario <- factor(
  table_long$FIT_sensitivity_scenario,
  levels = scenario_order
)
table_long <- table_long[order(
  table_long$Lesion_key,
  table_long$Estimand,
  table_long$FIT_sensitivity_scenario
), ]

long_export <- data.frame(
  Lesion = table_long$Lesion,
  Estimand = as.character(table_long$Estimand),
  FIT_sensitivity_scenario = as.character(
    table_long$FIT_sensitivity_scenario
  ),
  Screening_data_share_percent = round(
    table_long$Screening_data_share_percent,
    1
  ),
  FIT_sensitivity_share_percent = round(
    table_long$FIT_sensitivity_share_percent,
    1
  ),
  Colonoscopy_sensitivity_share_percent = round(
    table_long$Colonoscopy_sensitivity_share_percent,
    1
  ),
  stringsAsFactors = FALSE
)

detection <- long_export[
  long_export$Estimand == "Lesion detection under universal colonoscopy",
  ,
  drop = FALSE
]
prevalence <- long_export[
  long_export$Estimand == "Prevalence",
  ,
  drop = FALSE
]
key <- function(data) {
  paste(data$Lesion, data$FIT_sensitivity_scenario, sep = "\r")
}
prevalence <- prevalence[
  match(key(detection), key(prevalence)),
  ,
  drop = FALSE
]
if (anyNA(prevalence$Lesion) ||
    !identical(key(detection), key(prevalence))) {
  stop("Detection and prevalence rows could not be matched.", call. = FALSE)
}

table_compact <- data.frame(
  Lesion = detection$Lesion,
  FIT_sensitivity_source = ifelse(
    detection$FIT_sensitivity_scenario == "PRENEC",
    "PRENEC-derived",
    "Literature-based"
  ),
  Detection_screening_data_percent =
    detection$Screening_data_share_percent,
  Detection_FIT_sensitivity_percent =
    detection$FIT_sensitivity_share_percent,
  Prevalence_screening_data_percent =
    prevalence$Screening_data_share_percent,
  Prevalence_FIT_sensitivity_percent =
    prevalence$FIT_sensitivity_share_percent,
  Prevalence_colonoscopy_sensitivity_percent =
    prevalence$Colonoscopy_sensitivity_share_percent,
  stringsAsFactors = FALSE
)

rounded_sums <- c(
  rowSums(table_compact[, 3:4, drop = FALSE]),
  rowSums(table_compact[, 5:7, drop = FALSE])
)
if (any(abs(rounded_sums - 100) > 0.05)) {
  stop("Rounded main-table shares do not sum to 100.0%.", call. = FALSE)
}
if (any(detection$Colonoscopy_sensitivity_share_percent != 0)) {
  stop("Colonoscopy sensitivity must not contribute to detection.", call. = FALSE)
}

write.table(
  long_export,
  file = file.path(
    output_directory,
    "table_variance_shares_base_a_both_sexes_long.tsv"
  ),
  sep = "\t",
  row.names = FALSE,
  quote = FALSE
)
write.table(
  table_compact,
  file = file.path(
    output_directory,
    "table_variance_shares_base_a_both_sexes.tsv"
  ),
  sep = "\t",
  row.names = FALSE,
  quote = FALSE
)

body_lines <- vapply(seq_len(nrow(table_compact)), function(i) {
  row <- table_compact[i, , drop = FALSE]
  lesion_display <- if (
    row$FIT_sensitivity_source == "Literature-based"
  ) "" else row$Lesion
  line <- sprintf(
    paste0(
      "%s & %s & %.1f & %.1f & %.1f & %.1f & %.1f ",
      "\\\\"
    ),
    lesion_display,
    row$FIT_sensitivity_source,
    row$Detection_screening_data_percent,
    row$Detection_FIT_sensitivity_percent,
    row$Prevalence_screening_data_percent,
    row$Prevalence_FIT_sensitivity_percent,
    row$Prevalence_colonoscopy_sensitivity_percent
  )
  if (row$FIT_sensitivity_source == "Literature-based" &&
      i < nrow(table_compact)) {
    line <- paste0(line, "\n\\addlinespace[2pt]")
  }
  line
}, character(1))

latex_lines <- c(
  "\\begin{table}[htbp]",
  "\\centering",
  paste0(
    "\\caption{Sources of uncertainty in lesion detection under universal ",
    "colonoscopy and prevalence for FIT assignment A, both sexes.}"
  ),
  "\\label{tab:variance-shares-base-a}",
  "\\small",
  "\\setlength{\\tabcolsep}{4pt}",
  "\\begin{tabular}{@{}llrrrrr@{}}",
  "\\toprule",
  paste0(
    "& & \\multicolumn{2}{c}{Detection under universal colonoscopy} & ",
    "\\multicolumn{3}{c}{Prevalence} \\\\"
  ),
  "\\cmidrule(lr){3-4} \\cmidrule(l){5-7}",
  paste0(
    "Lesion & FIT sensitivity source & Data & FIT & Data & FIT & ",
    "Colonoscopy \\\\"
  ),
  "\\midrule",
  body_lines,
  "\\bottomrule",
  "\\end{tabular}",
  "\\vspace{2pt}",
  "\\begin{minipage}{\\textwidth}",
  "\\footnotesize",
  paste0(
    "\\textit{Note:} Values are percentages and sum to 100.0\\% within ",
    "each FIT-sensitivity scenario and estimand. Data denotes the empirical ",
    "screening component estimated by joint participant bootstrap. Total ",
    "attributable variance was defined as the sum of the separately estimated ",
    "log-variance components under independence. Colonoscopy-sensitivity ",
    "uncertainty does not enter lesion detection under universal colonoscopy. ",
    "PRENEC-derived colorectal-cancer FIT-sensitivity uncertainty followed ",
    "$\\operatorname{Beta}(6.5,0.5)$, based on six FIT-positive cancer cases."
  ),
  "\\end{minipage}",
  "\\end{table}"
)
writeLines(
  latex_lines,
  con = file.path(
    output_directory,
    "table_variance_shares_base_a_both_sexes.tex"
  ),
  useBytes = TRUE
)

markdown_lines <- c(
  paste0(
    "| Lesion | FIT sensitivity source | Detection: data | Detection: FIT | ",
    "Prevalence: data | Prevalence: FIT | Prevalence: colonoscopy |"
  ),
  "|---|---|---:|---:|---:|---:|---:|",
  vapply(seq_len(nrow(table_compact)), function(i) {
    row <- table_compact[i, , drop = FALSE]
    sprintf(
      "| %s | %s | %.1f%% | %.1f%% | %.1f%% | %.1f%% | %.1f%% |",
      row$Lesion,
      row$FIT_sensitivity_source,
      row$Detection_screening_data_percent,
      row$Detection_FIT_sensitivity_percent,
      row$Prevalence_screening_data_percent,
      row$Prevalence_FIT_sensitivity_percent,
      row$Prevalence_colonoscopy_sensitivity_percent
    )
  }, character(1)),
  "",
  paste0(
    "Note: Values are percentage shares of the assumed additive log-scale ",
    "variance and sum to 100.0% within each FIT-sensitivity scenario and ",
    "estimand."
  )
)
writeLines(
  markdown_lines,
  con = file.path(
    output_directory,
    "table_variance_shares_base_a_both_sexes.md"
  ),
  useBytes = TRUE
)

expected_outputs <- file.path(
  output_directory,
  c(
    "table_variance_shares_base_a_both_sexes_long.tsv",
    "table_variance_shares_base_a_both_sexes.tsv",
    "table_variance_shares_base_a_both_sexes.tex",
    "table_variance_shares_base_a_both_sexes.md"
  )
)
if (any(!file.exists(expected_outputs)) ||
    any(file.info(expected_outputs)$size <= 0)) {
  stop("One or more main-table outputs were not written correctly.", call. = FALSE)
}

message(
  "Main-text variance-share table written to: ",
  normalizePath(output_directory, winslash = "/", mustWork = TRUE)
)
